import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.where(rem >= 0, -np.exp(rem), -np.inf)
    if len(bins) > 0:
        max_cap = np.max(bins) if np.max(bins) > 0 else 1.0
        empty_mask = (bins == max_cap) & (rem >= 0)
        if np.any(empty_mask):
            scores[np.argmax(empty_mask)] = -np.exp(max_cap) * 2.0
    return scores
```

